package com.lma.app;
import com.lma.app.core.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;

/** Actual metadata/pair persistence and HTTP chain routes. Execution and Android codecs are excluded. */
public final class ConversationIntegrationTest {
    private static int checks;
    private interface Run{void run()throws Exception;}
    private static void ok(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static void rejects(Run call,String label)throws Exception{boolean failed=false;try{call.run();}catch(Exception expected){failed=true;}ok(failed,label);}
    private static JSONObject response(int port,String verb,String path,JSONObject body,String key,boolean auth)throws Exception{
        HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+path).openConnection();c.setConnectTimeout(2000);c.setReadTimeout(3000);c.setRequestMethod(verb);if(auth)c.setRequestProperty("Authorization","Bearer conversation-fixture");if(key!=null)c.setRequestProperty("Idempotency-Key",key);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");byte[] bytes=body.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}
        try{int status=c.getResponseCode();InputStream in=status>=400?c.getErrorStream():c.getInputStream();String text;try(InputStream owned=in){text=owned==null?"{}":new String(owned.readAllBytes(),StandardCharsets.UTF_8);}return new JSONObject().put("status",status).put("body",new JSONObject(text));}finally{c.disconnect();}
    }
    public static void main(String[] args)throws Exception{
        File repo=new File(args[0]),root=new File(args[1]);root.mkdirs();LmaApp app=new LmaApp(new File(root,"app"),new File(repo,"app/src/main/assets"),new File(repo,"app/src/main/jniLibs/arm64-v8a"));app.capabilities=new ModelCapabilities(app);app.visionPairs=new VisionPairs(app);JSONArray models=app.store.snapshot();ok(models.length()==14,"all exact variants retained");
        for(int i=0;i<models.length();i++){JSONObject m=models.getJSONObject(i),d=app.capabilities.describe(m);ok(d.getJSONArray("native").length()>=7,"full capability fields "+m.getString("id"));ok(!d.getJSONObject("evidence").getBoolean("phoneOutput"),"metadata never becomes phone evidence");}
        JSONObject unknown=app.capabilities.describe(new JSONObject().put("id","unknown_custom"));ok(unknown.getJSONArray("native").getJSONObject(0).getString("support").equals("unknown"),"unknown is not unsupported");
        JSONObject preset;try(InputStream in=app.getAssets().open("vision-presets.json")){preset=new JSONObject(Store.read(in,65536)).getJSONArray("presets").getJSONObject(0);}JSONObject paired=app.visionPairs.bind(preset);String component=paired.getString("bundleId");app.bundles.removalGuard(id->app.visionPairs.referencesBundle(id));
        ok(!app.bundles.plan(component).getBoolean("installed"),"saving pair does not download or install projector");ok(app.visionPairs.snapshot().getJSONObject(0).getBoolean("installed")==false,"local missing state remains explicit");ok(app.bundles.bundle(component).component("projector").bytes==675568768L,"exact pinned projector bytes retained");
        rejects(()->app.bundles.remove(component,false),"paired shared component deletion blocked");
        JSONObject wrong=DataFiles.copy(preset).put("mainSha256","0".repeat(64));rejects(()->app.visionPairs.bind(wrong),"different main identity rejected");
        JSONObject textOnly=DataFiles.copy(preset).put("modelId","m05").put("userReviewedCompatibility",true);rejects(()->app.visionPairs.bind(textOnly),"Gemma 1B cannot inherit the 4B visual route");
        ok(new VisionPairs(app).pair("m15").getString("bundleId").equals(component),"pair survives actual AtomicFile reopening");app.visionPairs.unbind("m15");app.bundles.remove(component,false);ok(app.visionPairs.pair("m15")==null,"explicit unbind releases pair reference only");
        final WorkflowStore chains=new WorkflowStore(new File(root,"http-chains"));LocalApi.Runtime runtime=new LocalApi.Runtime(){
            public String apiKey(){return "conversation-fixture";}public JSONObject health(){return new JSONObject();}public JSONArray models(){JSONArray result=new JSONArray();for(String[] m:new String[][]{{"image_model","image.generate"},{"voice_model","speech.synthesize"}})result.put(new JSONObject().put("id",m[0]).put("bundle_id",m[0]).put("x_lma",new JSONObject().put("operations",new JSONArray().put(m[1]))));return result;}
            public JSONArray engines(){return new JSONArray();}public JobStore jobs(){return app.jobs;}public ArtifactStore artifacts(){return app.artifacts;}public JSONObject submit(JSONObject r,String key)throws Exception{throw new IOException("No inference in fixture");}public void cancel(String id){}public LocalHttp.Response text(String path,JSONObject r)throws Exception{throw new IOException("No inference in fixture");}public boolean localComposition(){return true;}public WorkflowStore workflows(){return chains;}public JSONObject createChain(JSONObject draft,String key)throws Exception{return chains.create(draft,"private_session",key);}
        };
        JSONObject image=new JSONObject().put("model","image_model").put("type","image.generate").put("input",new JSONObject().put("prompt","fixture")).put("allowUnmeasured",true),voice=new JSONObject().put("model","voice_model").put("type","speech.synthesize").put("input",new JSONObject().put("prompt","fixture"));
        JSONObject compose=new JSONObject().put("model",CompositionSpec.ID).put("type","media.compose").put("input",new JSONObject().put("prompt","compose"));
        JSONObject draft=new JSONObject().put("template","HTTP-W05").put("steps",new JSONArray().put(new JSONObject().put("request",image)).put(new JSONObject().put("request",voice)).put(new JSONObject().put("request",compose).put("dependsOn",new JSONArray().put(0).put(1)).put("bindings",new JSONArray().put(new JSONObject().put("step",0).put("role","visual")).put(new JSONObject().put("step",1).put("role","voice")))));
        try(LocalHttp server=new LocalHttp("127.0.0.1",0,new LocalApi(runtime))){int port=server.port();String path="/v1/lma/chains";
            ok(response(port,"POST",path,draft,"http-key",false).getInt("status")==401,"chain API requires authentication");ok(response(port,"POST",path,draft,null,true).getInt("status")>=400,"chain API requires stable idempotency key");
            JSONObject first=response(port,"POST",path,draft,"http-key",true);ok(first.getInt("status")==202,"future composition bindings accepted by actual HTTP facade");JSONObject body=first.getJSONObject("body");String id=body.getString("id");ok(!body.has("session"),"private session excluded from API");ok(body.getJSONArray("steps").getJSONObject(0).getJSONObject("request").getBoolean("allowUnmeasured"),"explicit caller consent survives mapping");
            ok(response(port,"POST",path,draft,"http-key",true).getJSONObject("body").getString("id").equals(id),"HTTP retry attaches original chain");JSONObject changed=DataFiles.copy(draft).put("template","changed");ok(response(port,"POST",path,changed,"http-key",true).getInt("status")>=400,"changed payload cannot reuse key");
            ok(response(port,"GET",path+"/"+id,null,null,true).getInt("status")==200,"chain query roundtrip");ok(response(port,"POST",path+"/"+id+"/cancel",new JSONObject(),null,true).getJSONObject("body").getBoolean("cancelRequested"),"HTTP cancellation reaches durable parent state");ok(response(port,"GET",path,null,null,true).getJSONObject("body").getJSONArray("data").length()==1,"listing has one original chain, no duplicate");
        }
        System.out.println(new JSONObject().put("passed",checks).put("checks",checks).put("physical_device_tests",0).put("model_inference",false).put("actual_http",true));
    }
}
